import{_ as a,o as t,c as n,a6 as i}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Adapter des recettes pratiques d’automatisation","description":"","frontmatter":{"title":"Adapter des recettes pratiques d’automatisation","docId":"user.automations.recipes","translationKey":"user.automations.recipes","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"43a103ef68e43d691eec2214ffefb5e2e0e6b663afa9f4e63b5dac0ccec162ea","translationRevision":"6d71c3a0b25f94ce7e39fa1aed1b7b605c3f0bfe6f6d003a34c247df92ed1326","order":30},"headers":[],"relativePath":"fr/user/automations/recipes.md","filePath":"fr/user/automations/recipes.md","lastUpdated":1794611623000}'),s={name:"fr/user/automations/recipes.md"};function o(r,e,c,d,u,l){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="adapt-practical-automation-recipes" tabindex="-1">Adapter des recettes pratiques d’automatisation <a class="header-anchor" href="#adapt-practical-automation-recipes" aria-label="Permalink to &quot;Adapter des recettes pratiques d’automatisation {#adapt-practical-automation-recipes}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Transformer une <a href="./first-rule.html">règle de journalisation</a> fonctionnelle en réactions précisément ciblées. Il faut un profil actif et des champs d’événement observés. Commencez avec des actions <code>core.log</code> ; remplacez-les par un autre effet seulement après avoir confirmé la correspondance et la fréquence.</p><h2 id="match-a-chat-command" tabindex="-1">Reconnaître une commande de discussion <a class="header-anchor" href="#match-a-chat-command" aria-label="Permalink to &quot;Reconnaître une commande de discussion {#match-a-chat-command}&quot;">​</a></h2><p>Créez un événement <code>tiktok.chat</code> avec <code>event.data.comment</code> égal (<code>eq</code>) à <code>!bonjour</code>. Journalisez :</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Bonjour {{ event.user.uniqueId }}</span></span></code></pre></div><p>Utilisez un délai par utilisateur de <code>30</code> secondes pour qu’un spectateur ne puisse pas le déclencher continuellement, tout en laissant aux autres une possibilité indépendante. L’égalité exacte convient à une commande ; une correspondance par contenu accepte aussi les messages avec du texte autour. Choisissez délibérément.</p><h2 id="record-a-qualifying-gift" tabindex="-1">Enregistrer un cadeau répondant au critère <a class="header-anchor" href="#record-a-qualifying-gift" aria-label="Permalink to &quot;Enregistrer un cadeau répondant au critère {#record-a-qualifying-gift}&quot;">​</a></h2><p>Créez un événement <code>tiktok.gift</code> avec <code>event.data.diamondCount</code> supérieur ou égal (<code>gte</code>) à <code>10</code>. Journalisez :</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cadeau {{ event.data.giftName }} de {{ event.user.uniqueId }}</span></span></code></pre></div><p>Examinez d’abord les détails des cadeaux réels. La valeur en diamants, le nombre de répétitions et l’indicateur de fin d’un cadeau sont des champs différents. Si vous souhaitez réagir uniquement à la fin, vérifiez que la charge utile entrante fournit <code>event.data.repeatEnd</code>, puis utilisez la condition booléenne vraie. Un filtre sur le nom seul ne garantit pas une exécution par série terminée.</p><h2 id="bound-a-shared-reaction" tabindex="-1">Limiter une réaction partagée <a class="header-anchor" href="#bound-a-shared-reaction" aria-label="Permalink to &quot;Limiter une réaction partagée {#bound-a-shared-reaction}&quot;">​</a></h2><p>Créez un événement <code>tiktok.follow</code> avec un délai global de <code>10</code> secondes. Reliez une courte action de journalisation. Si deux spectateurs s’abonnent dans cet intervalle, le délai global peut supprimer la réaction suivante. Utilisez plutôt une portée par utilisateur lorsque chacun doit disposer de sa propre autorisation.</p><p>Pour plusieurs actions, ordonnez la liste et conservez le mode exécutant toutes les actions lorsque chaque étape est nécessaire. Le mode aléatoire choisit une action ; il n’exécute pas toutes les étapes dans un ordre aléatoire. Ajoutez <code>core.delay</code> uniquement lorsque les étapes suivantes doivent attendre.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>Ces déclencheurs, filtres de champs et commandes de délai sont disponibles dans le moteur local. Une exécution doit correspondre à un événement accepté satisfaisant les critères, sous réserve du délai et de l’activation. La validation propre au fournisseur nécessite toujours votre vérification LIVE réelle.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Récupération {#recovery}&quot;">​</a></h2><p>Si une recette échoue, revenez à une seule action de journalisation, examinez la charge utile et simplifiez temporairement les conditions. Ne désactivez pas les limites sur une diffusion chargée pendant l’enquête. Les tests audio, points, HTTP et plugins peuvent produire des effets réels. Consultez la <a href="./../plugins/audio.html">configuration audio</a>, les <a href="./variables.html">variables</a> et les <a href="./../preferences/troubleshooting.html">diagnostics d’exécution</a> avant d’ajouter ces dépendances.</p>',18)])])}const h=a(s,[["render",o]]);export{m as __pageData,h as default};
